#!/usr/bin/env python3
"""
UnityBotV4 — Server-side interactive CLI
==========================================

A standalone REPL for talking to Unity from a server (SSH session, tmux, etc.)
without a Discord client. Reuses the bot's `Config` + `APIClient` so token
handling, endpoint selection, and retry behavior all stay consistent with the
running bot.

Features:
  - Chat with any Pollinations model (default: unity)
  - Per-session conversation history (cleared with !clear)
  - Inline image rendering in the terminal — auto-detects chafa / viu /
    kitty +kitten icat; falls back to printing the Pollinations URL so it can
    be opened in a browser or via SSH port-forward
  - !image <prompt> — direct image generation that bypasses chat
  - All generated images saved to ./generated_images/<timestamp>.png

Usage:
    python unity_cli.py
    python unity_cli.py --model openai
    python unity_cli.py --save-dir /var/lib/unity/images
    python unity_cli.py --no-render          # save+print URL, never try terminal display
    python unity_cli.py --renderer chafa     # force a specific renderer

Inside the REPL:
    just type                  → chat
    !image <prompt>            → direct image-gen bypass
    !model <name>              → switch active model
    !history                   → print conversation
    !clear                     → clear conversation history
    !render <on|off>           → toggle terminal image rendering
    !show <path-or-url>        → re-render an image you generated earlier
    !help                      → command reference
    !quit / !exit / Ctrl-D     → leave
"""

from __future__ import annotations

import argparse
import asyncio
import os
import re
import shutil
import subprocess
import sys
import time
from datetime import datetime
from io import BytesIO
from pathlib import Path
from typing import Optional

import aiohttp

# Reuse the bot's Config + APIClient — same env, same endpoint selection
from config import Config
from api_client import APIClient


# ─── Renderer auto-detect ───────────────────────────────────────────────────

# Order matters: chafa is most portable (terminfo-aware), viu is solid cross-platform,
# kitty's icat only works in kitty/wezterm but renders losslessly.
RENDERER_CANDIDATES = [
    ("chafa", ["chafa", "--version"]),
    ("viu", ["viu", "--version"]),
    ("kitty", ["kitty", "+kitten", "icat", "--help"]),
    ("imgcat", ["imgcat", "--version"]),
    ("wezterm-imgcat", ["wezterm", "imgcat", "--help"]),
]


def detect_renderer() -> Optional[str]:
    """Return the first renderer found on PATH, or None."""
    for name, probe_cmd in RENDERER_CANDIDATES:
        binary = probe_cmd[0]
        if shutil.which(binary) is None:
            continue
        # Probe to make sure it's invokable (handles broken installs)
        try:
            subprocess.run(
                probe_cmd,
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                timeout=3,
                check=False,
            )
            return name
        except Exception:
            continue
    return None


def render_image(renderer: str, image_path: Path, *, max_cols: int = 80) -> bool:
    """Render an image inline in the terminal using the chosen tool.

    Returns True on apparent success, False on failure.
    """
    try:
        if renderer == "chafa":
            cmd = ["chafa", "--size", f"{max_cols}x", str(image_path)]
        elif renderer == "viu":
            cmd = ["viu", "-w", str(max_cols), str(image_path)]
        elif renderer == "kitty":
            cmd = ["kitty", "+kitten", "icat", "--align", "left", str(image_path)]
        elif renderer == "imgcat":
            cmd = ["imgcat", str(image_path)]
        elif renderer == "wezterm-imgcat":
            cmd = ["wezterm", "imgcat", str(image_path)]
        else:
            return False
        subprocess.run(cmd, check=False)
        return True
    except Exception as e:
        print(f"  [render failed via {renderer}: {e}]")
        return False


# ─── Helpers ────────────────────────────────────────────────────────────────

URL_RE = re.compile(r"https?://[^\s>'\"]+")
PREFIX_RE = re.compile(r"^\s*\[(?:claude|revclaude|gpt|openai|assistant)\]\s*:?\s*", re.IGNORECASE)


def clean_response(text: str) -> str:
    """Mirror MessageHandler.clean_response — strip model prefixes + noise lines."""
    text = text.strip()
    text = PREFIX_RE.sub("", text)
    text = re.sub(r"\n{3,}", "\n\n", text)
    lines = [
        line for line in text.split("\n")
        if not re.match(r"^---", line)
        and "Generated by" not in line
        and not re.search(r"\d{4}-\d{2}-\d{2}", line)
    ]
    return "\n".join(lines).strip()


def timestamp_filename(prefix: str = "image", ext: str = "png") -> str:
    return f"{prefix}_{datetime.now().strftime('%Y%m%d_%H%M%S_%f')[:-3]}.{ext}"


async def download_image(session: aiohttp.ClientSession, url: str, save_path: Path) -> bool:
    """Download a URL to disk. Returns True on success."""
    try:
        async with session.get(url, timeout=aiohttp.ClientTimeout(total=60)) as resp:
            if resp.status != 200:
                print(f"  [download failed: status {resp.status} for {url}]")
                return False
            content = await resp.read()
            save_path.write_bytes(content)
            return True
    except Exception as e:
        print(f"  [download error: {e}]")
        return False


# ─── REPL state ─────────────────────────────────────────────────────────────

class CliSession:
    def __init__(
        self,
        config: Config,
        api_client: APIClient,
        *,
        model: str,
        save_dir: Path,
        renderer: Optional[str],
        render_enabled: bool,
        render_cols: int,
    ):
        self.config = config
        self.api_client = api_client
        self.model = model
        self.save_dir = save_dir
        self.renderer = renderer
        self.render_enabled = render_enabled
        self.render_cols = render_cols
        self.history: list[dict] = []
        self.aiohttp_session: Optional[aiohttp.ClientSession] = None

    async def ensure_aiohttp(self) -> aiohttp.ClientSession:
        if self.aiohttp_session is None or self.aiohttp_session.closed:
            self.aiohttp_session = aiohttp.ClientSession()
        return self.aiohttp_session

    async def close(self) -> None:
        if self.aiohttp_session and not self.aiohttp_session.closed:
            await self.aiohttp_session.close()
        await self.api_client.close()

    async def handle_image_command(self, prompt: str) -> None:
        """!image <prompt> — bypass chat, hit Pollinations image endpoint directly."""
        if not prompt:
            print("  usage: !image <prompt>")
            return
        url = self.config.image_url(prompt, model="flux", width=1024, height=1024)
        print(f"  → generating: {prompt}")
        print(f"  url: {url}")
        save_path = self.save_dir / timestamp_filename("direct")
        session = await self.ensure_aiohttp()
        if await download_image(session, url, save_path):
            print(f"  ✓ saved: {save_path}")
            await self.show_image(save_path, url)

    async def handle_chat(self, user_text: str) -> None:
        """Normal chat turn — sends through Pollinations, parses + downloads any image URLs."""
        self.history.append({"role": "user", "content": user_text})

        system_prompt = f"{self.config.system_instructions}\nYou are {self.model}."
        messages = [{"role": "system", "content": system_prompt}, *self.history]

        print("  ...")
        response = await self.api_client.send_message(messages, self.model)

        if isinstance(response, str) and response.startswith("Error:"):
            print(f"  ✗ {response}")
            self.history.pop()  # don't poison the history with an unanswered turn
            return

        cleaned = clean_response(response)
        if not cleaned:
            print("  ✗ empty response from API")
            self.history.pop()
            return

        # Extract and download any image URLs
        urls = URL_RE.findall(cleaned)
        text_only = URL_RE.sub("", cleaned).strip()

        if text_only:
            print()
            print(text_only)

        if urls:
            session = await self.ensure_aiohttp()
            for url in urls:
                save_path = self.save_dir / timestamp_filename("chat")
                print(f"\n  → downloading: {url}")
                if await download_image(session, url, save_path):
                    print(f"  ✓ saved: {save_path}")
                    await self.show_image(save_path, url)

        # Record assistant turn
        self.history.append({"role": "assistant", "content": cleaned})

    async def show_image(self, path: Path, url: Optional[str] = None) -> None:
        """Render an image visually if possible, else print the URL prominently."""
        if self.render_enabled and self.renderer:
            ok = render_image(self.renderer, path, max_cols=self.render_cols)
            if ok:
                return
        # Fallback — make the URL stand out
        bar = "─" * 60
        print(f"\n  {bar}")
        print(f"  IMAGE READY (terminal renderer unavailable or disabled)")
        print(f"  file: {path}")
        if url:
            print(f"  url:  {url}")
        print(f"  {bar}\n")

    async def handle_command(self, line: str) -> bool:
        """Return False if the user wants to exit."""
        parts = line.split(None, 1)
        cmd = parts[0].lower()
        arg = parts[1] if len(parts) > 1 else ""

        if cmd in ("!quit", "!exit"):
            print("  bye")
            return False
        if cmd == "!help":
            print(__doc__.split("Inside the REPL:")[1].rstrip())
            return True
        if cmd == "!model":
            if not arg:
                print(f"  current model: {self.model}")
            else:
                self.model = arg
                print(f"  switched to model: {self.model}")
            return True
        if cmd == "!history":
            if not self.history:
                print("  (empty)")
            for i, msg in enumerate(self.history, 1):
                print(f"  {i:2d}. [{msg['role']}] {msg['content'][:200]}")
            return True
        if cmd == "!clear":
            self.history.clear()
            print("  history cleared")
            return True
        if cmd == "!render":
            if arg.lower() in ("on", "true", "1", "yes"):
                self.render_enabled = True
                print(f"  render: on (renderer: {self.renderer or 'none-detected'})")
            elif arg.lower() in ("off", "false", "0", "no"):
                self.render_enabled = False
                print("  render: off")
            else:
                print(f"  render: {'on' if self.render_enabled else 'off'}  renderer: {self.renderer or 'none'}")
            return True
        if cmd == "!show":
            if not arg:
                print("  usage: !show <path-or-url>")
                return True
            if arg.startswith(("http://", "https://")):
                save_path = self.save_dir / timestamp_filename("reshow")
                session = await self.ensure_aiohttp()
                if await download_image(session, arg, save_path):
                    print(f"  ✓ saved: {save_path}")
                    await self.show_image(save_path, arg)
            else:
                p = Path(arg).expanduser()
                if not p.exists():
                    print(f"  ✗ no such file: {p}")
                    return True
                await self.show_image(p)
            return True
        if cmd == "!image":
            await self.handle_image_command(arg)
            return True

        print(f"  unknown command: {cmd}  (try !help)")
        return True


# ─── Entrypoint ─────────────────────────────────────────────────────────────

async def amain(args: argparse.Namespace) -> int:
    print("=" * 60)
    print("UnityBotV4 — Server CLI")
    print("=" * 60)

    # Load config (validates Discord + Pollinations env at startup — Discord
    # token isn't actually used by the CLI but the bot's Config requires it.
    # If you want to skip the Discord check, set DISCORD_TOKEN to any valid-
    # format placeholder.)
    try:
        config = Config()
    except (ValueError, FileNotFoundError) as e:
        print(f"  ✗ config error: {e}")
        print("  fix: run `python configure.py` and try again")
        return 1

    print(f"  pollinations stack: {config.pollinations_stack}")
    print(f"  chat endpoint:      {config.chat_url}")
    print(f"  models endpoint:    {config.models_url}")
    print(f"  image base:         {config.image_base}")

    # Renderer detection
    if args.renderer:
        renderer = args.renderer
        if shutil.which(renderer.split()[0]) is None:
            print(f"  ! warning: requested renderer '{renderer}' not on PATH — falling back to URL display")
            renderer = None
    elif args.no_render:
        renderer = None
    else:
        renderer = detect_renderer()
    print(f"  renderer:           {renderer or 'none (URL fallback)'}")

    # Save dir
    save_dir = Path(args.save_dir).expanduser().resolve()
    save_dir.mkdir(parents=True, exist_ok=True)
    print(f"  save dir:           {save_dir}")

    api_client = APIClient(config)
    await api_client.initialize()

    session = CliSession(
        config=config,
        api_client=api_client,
        model=args.model,
        save_dir=save_dir,
        renderer=renderer,
        render_enabled=not args.no_render,
        render_cols=args.render_cols,
    )

    print(f"\n  model: {session.model}    type `!help` for commands, `!quit` to exit\n")

    try:
        while True:
            try:
                line = input("unity> ").strip()
            except EOFError:
                print()
                break
            except KeyboardInterrupt:
                print("\n  (interrupted — type !quit to exit)")
                continue
            if not line:
                continue
            if line.startswith("!"):
                keep_going = await session.handle_command(line)
                if not keep_going:
                    break
            else:
                await session.handle_chat(line)
    finally:
        await session.close()

    return 0


def main() -> int:
    parser = argparse.ArgumentParser(description="UnityBotV4 server-side CLI")
    parser.add_argument("--model", default="unity", help="Pollinations model name (default: unity)")
    parser.add_argument("--save-dir", default="generated_images",
                        help="Directory for saved images (default: ./generated_images)")
    parser.add_argument("--no-render", action="store_true",
                        help="Don't try to render images in the terminal — just save + print URL")
    parser.add_argument("--renderer", default=None,
                        help="Force a specific terminal renderer (chafa / viu / kitty / imgcat / wezterm-imgcat)")
    parser.add_argument("--render-cols", type=int, default=80,
                        help="Terminal columns to render images at (default: 80)")
    args = parser.parse_args()

    try:
        return asyncio.run(amain(args))
    except KeyboardInterrupt:
        return 130


if __name__ == "__main__":
    sys.exit(main())
